import '@servicenow/sdk/global'
import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

// Flow that defines a repeat scheduled trigger at a specific time.

Flow(
    {
        $id: Now.ID['flow_def_datatypes_test'],
        name: 'Flow - Data Types Test',
        description: 'Flow used by tests to validate data types.',
    },
    wfa.trigger(
        trigger.scheduled.daily,
        {
            $id: Now.ID['flow_def_datatypes_test_trigger'],
            annotation: 'Daily scheduled trigger at 10:00:00',
        },
        {
            time: Time({ hours: 10, minutes: 30, seconds: 15 }),
        }
    ),
    () => {
        const actionInstance1 = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['flow_def_datatypes_test_step1'],
                annotation: 'Create a new incident',
            },
            {
                table_name: 'incident',
                values: TemplateValue({
                    category: 'network',
                    short_description: 'VPN issue',
                    priority: '1',
                }),
            }
        )
        wfa.action(
            action.core.sendEmail,
            {
                $id: Now.ID['flow_def_datatypes_test_step2'],
                annotation: 'Send an email',
            },
            {
                record: wfa.dataPill(actionInstance1.record, 'reference'),
                watermark_email: true,
                ah_to: `${wfa.dataPill(actionInstance1.record.assigned_to.email, 'string')}`,
                ah_subject: `Incident assigned : ${wfa.dataPill(actionInstance1.record.number, 'string')}`,
                // ah_body: Now.include('./html/incident-assigned-body.html'),
                ah_body: 'Hello everyone,\n\nPlease look into the incident.',
            }
        )
    }
)
